#include "can_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void can_msg_wr (Can_IO_Base can_io_base , Can_Msg * can_msg , Can_Tx_Id can_tx_id)
{
  typedef struct s_Tx_Ctrl
    {
      UInt8  CANTID     ; 
      UInt8  CANTFI     ;
      UInt8  CANTDA     ;
      UInt8  CANTDB     ;
  
    } Tx_Ctrl ;
  
  static const Tx_Ctrl tx_ctrl_table [] =
    {
      { CANTID1 , CANTFI1 , CANTDA1 , CANTDB1 } ,
      { CANTID2 , CANTFI2 , CANTDA2 , CANTDB2 } ,
      { CANTID3 , CANTFI3 , CANTDA3 , CANTDB3 } ,
    } ;

  const Tx_Ctrl * const tx_ctrl  = & tx_ctrl_table [can_tx_id] ;

  #define REG(z) can_io_base [tx_ctrl->z]
  
  REG (CANTID) = can_msg->id ;
  
  REG (CANTFI) = ((UInt32) can_msg->length << 16) | (can_msg->is_rtr ? 1ul << 30 : 0) | (can_msg->is_ext ? 1ul << 31 : 0)  | ((UInt8) REG (CANTFI)) ;
  
  REG (CANTDA) = can_msg->data._32_ [0] ; 
  REG (CANTDB) = can_msg->data._32_ [1] ; 

  #undef  REG
}

